contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes two inputs: amount to deposit and a flag whether to withdraw afterwards
    function run(uint256 amount, bool doWithdraw) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // read before-deposit values
        uint256 beforeUser = c.getBalance(address(this));
        uint256 beforeContractBal = address(c).balance;

        // perform deposit: send `amount` wei to c via addToBalance
        c.addToBalance{value: amount}();

        // read after-deposit values
        uint256 afterUser = c.getBalance(address(this));
        uint256 afterContractBal = address(c).balance;

        bool withdrew = false;
        uint256 afterUserFinal = afterUser;
        uint256 afterContractBalFinal = afterContractBal;

        if (doWithdraw) {
            // attempt withdrawal and observe effect
            // capture revert or success
            bool reverted;
            try c.withdrawBalance() {
                reverted = false;
            } catch {
                reverted = true;
            }
            // If not reverted, read final balances
            if (!reverted) {
                afterUserFinal = c.getBalance(address(this));
                afterContractBalFinal = address(c).balance;
                withdrew = true;
            }
        }

        // General rule to assert:
        // 1) The user's recorded balance increases exactly by amount after addToBalance.
        // 2) The contract's Ether balance increases exactly by amount after addToBalance.
        // 3) If withdrawBalance was called and did not revert, then the user's recorded balance becomes 0 and the contract's Ether balance decreases by the same amount that had been added.
        assert(
            // deposit effects
            afterUser == beforeUser + amount
            && afterContractBal == beforeContractBal + amount
            // withdraw effects if executed successfully
            && ( !doWithdraw || ( doWithdraw && ( (withdrew && afterUserFinal == 0 && afterContractBalFinal + amount == afterContractBal) ) ) )
        );
    }

    // Allow receiving Ether when withdrawBalance calls back
    receive() external payable { }
}

