contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(uint topUp) public payable {
        require(address(this).balance >= topUp, "insufficient balance for topUp");

        // Record balance before any operations
        uint beforeRecorded = c.getBalance(address(this));
        uint beforeContractBal = address(c).balance;

        // Optionally increase recorded balance by sending Ether to addToBalance
        // Use topUp as the amount to send; it may be zero.
        if (topUp > 0) {
            c.addToBalance{value: topUp}();
        }

        // Read recorded balance after possible topUp
        uint afterRecorded = c.getBalance(address(this));
        uint afterContractBal = address(c).balance;

        // Now attempt withdrawBalance and observe whether it reverts
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Recorded balance after the withdraw attempt
        uint finalRecorded = c.getBalance(address(this));
        uint finalContractBal = address(c).balance;

        // General rule:
        // If withdrawBalance succeeded (did not revert) then final recorded balance must be zero
        // and contract balance must have decreased by at least the recorded amount that was present just before withdraw.
        // If withdrawBalance reverted then the recorded balance must be unchanged from before the call.
        assert((!reverted && finalRecorded == 0 && afterContractBal >= finalContractBal && (afterContractBal - finalContractBal) >= afterRecorded) || (reverted && finalRecorded == afterRecorded));
    }

    // Allow receiving Ether for topUp funding
    receive() external payable {}
}

